  let mut vault=Vault::create(&dir.join("workspace.atlas"),"secret").unwrap();vault.set_workspace_name("old").unwrap();vault.put_note("note","title","old").unwrap();vault.put_file("file","f.bin",&b"a"[..],None).unwrap();
